// The whole web UI, served by n8n. Edit the markup here and it is live on the
// next request - there is nothing to build and nowhere to deploy it.
// The page posts back to its own URL, so it works on the test and the
// production webhook without knowing either address.

const html = `<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>ResumeRadar</title>
<link rel="preconnect" href="https://fonts.googleapis.com">
<link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
