  .report { display:grid; gap:16px; margin-top:32px; }
  .summary { display:flex; align-items:center; gap:22px; flex-wrap:wrap;
             background:var(--surface); border:1px solid var(--line);
             border-radius:14px; padding:var(--pad); }
  .ring { --pct:0; flex:0 0 92px; width:92px; height:92px; border-radius:50%;
          display:grid; place-items:center;
          background:conic-gradient(from -90deg,
                     var(--kk-blue) 0, var(--kk-cyan) calc(var(--pct)*1%),
