  .verdict { flex:1 1 250px; }
  .verdict h2 { font-size:19px; font-weight:600; letter-spacing:-.3px; }
  .verdict .why { margin:6px 0 0; font-size:14px; color:var(--muted);
                  max-width:52ch; }
  .chip { display:inline-block; margin-top:12px; padding:4px 11px;
          border-radius:999px; font-family:var(--mono); font-size:12px;
          font-weight:500; }
  .chip.have { background:rgba(52,211,153,.13); color:var(--have); }
  .chip.gap  { background:rgba(251,113,133,.13); color:var(--gap); }

