             border:1px solid var(--line); }
  .tags.gap li { border-color:rgba(251,113,133,.42); color:#ffc2cb; }
  .tags.have li { border-color:rgba(52,211,153,.42); color:#a5edcb; }
  .tags.none li { color:var(--muted); font-family:var(--sans); }

  .panelhead { display:flex; align-items:center; justify-content:space-between;
               gap:12px; }
  .panelhead .eyebrow { margin:0; }
  .copy { font-family:var(--mono); font-size:12px; letter-spacing:.06em;
          text-transform:uppercase; color:var(--muted); background:transparent;
          border:1px solid var(--line); border-radius:8px; padding:6px 12px;
          cursor:pointer; }
  .copy:hover { color:var(--text); border-color:var(--kk-cyan); }
  .cv { margin:12px 0 0; white-space:pre-wrap; font-family:var(--sans);
        font-size:14.5px; line-height:1.6; background:var(--inset);
        border:1px solid var(--line); border-radius:10px; padding:18px;
        max-height:470px; overflow:auto; }
  .credit { margin:2px 0 0; font-family:var(--mono); font-size:12px;
            color:var(--muted); }
  .credit b { color:var(--text); font-weight:500; }

  footer { max-width:980px; margin:0 auto; padding:0 20px 60px;
           font-family:var(--mono); font-size:12px; color:var(--muted); }
  footer .rule { height:1px; background:var(--line); margin-bottom:16px; }
  @media (prefers-reduced-motion:reduce) { * { scroll-behavior:auto !important; } }
</style>
</head>
<body>
<header class="topbar">
  <div class="bar">
    <svg class="mark" viewBox="0 0 32 32" role="img" aria-label="KodeKloud">
      <defs><linearGradient id="kkg" x1="0" y1="0" x2="1" y2="1">
        <stop offset="0" stop-color="#2b7fff"></stop>
        <stop offset="1" stop-color="#3ec9de"></stop>
      </linearGradient></defs>
      <rect x="0" y="0" width="32" height="32" rx="9" fill="url(#kkg)"></rect>
      <path d="M13 9.5 L7.5 16 L13 22.5" fill="none" stroke="#0a1120"
            stroke-width="2.4" stroke-linecap="round" stroke-linejoin="round"></path>
      <path d="M19 9.5 L24.5 16 L19 22.5" fill="none" stroke="#0a1120"
            stroke-width="2.4" stroke-linecap="round" stroke-linejoin="round"></path>
    </svg>
    <span class="brandname">KodeKloud</span>
    <span class="divider"></span>
    <span class="product">KodeKey</span>
    <a class="getkey" href="https://kodekloud.com/ai-playgrounds/kodekey"
       target="_blank" rel="noopener">Get your key</a>
  </div>
</header>

<main>
  <section class="hero">
    <h1>ResumeRadar</h1>
    <p>Upload your CV, paste a job ad. You get a match score you can trace, an
    honest list of what the CV cannot show, and a rewritten version that
    invents nothing.</p>
    <span class="pill">One key &middot; every model</span>
  </section>

  <form class="panel" id="f">
    <div>
      <p class="eyebrow">Your CV</p>
      <input id="cv" type="file" name="CV" accept=".pdf" required>
      <label class="drop" for="cv"><b>Choose a PDF</b>
        <span id="fname">no file selected</span></label>
    </div>

    <div>
      <label class="eyebrow" for="job">The job ad</label>
      <textarea id="job" name="job_ad" required
                placeholder="Paste the whole posting, requirements and all"></textarea>
    </div>

    <button class="go" id="go" type="submit">Review my CV</button>
    <p class="status" id="status"></p>
  </form>

  <div id="result"></div>
</main>

<footer>
  <div class="rule"></div>
  Built on KodeKloud Playgrounds &middot; n8n for the workflow, KodeKey for the
  models &middot; three model calls, one credential
</footer>

<script>
  var form = document.getElementById('f');
  var go = document.getElementById('go');
  var statusEl = document.getElementById('status');
  var result = document.getElementById('result');
  var file = document.getElementById('cv');
  var fname = document.getElementById('fname');

  file.addEventListener('change', function () {
    fname.textContent = file.files.length ? file.files[0].name : 'no file selected';
  });

  // The workflow sends classes and data attributes. Behaviour lives here.
  function decorate() {
    var ring = result.querySelector('.ring');
    if (ring) { ring.style.setProperty('--pct', ring.dataset.score); }

    var pre = result.querySelector('.cv');
    var copy = result.querySelector('.copy');
    if (pre && copy) {
      copy.addEventListener('click', function () {
        navigator.clipboard.writeText(pre.textContent).then(function () {
          copy.textContent = 'Copied';
          setTimeout(function () { copy.textContent = 'Copy'; }, 1800);
        });
      });
    }
    result.scrollIntoView({ behavior: 'smooth', block: 'start' });
  }

  form.addEventListener('submit', function (e) {
    e.preventDefault();
    go.disabled = true;
    result.innerHTML = '';
    statusEl.className = 'status';
    statusEl.textContent = 'Reading the CV, then the job ad, then rewriting. '
      + 'Around fifteen seconds.';

    fetch(window.location.href, { method: 'POST', body: new FormData(form) })
      .then(function (r) {
        if (!r.ok) { throw new Error('The workflow returned ' + r.status); }
        return r.text();
      })
      .then(function (html) {
        if (!html.trim()) {
          throw new Error('The workflow returned an empty response, so no node '
            + 'reached Respond to Webhook');
        }
        statusEl.textContent = '';
        result.innerHTML = html;
        decorate();
      })
      .catch(function (err) {
        statusEl.className = 'status err';
        statusEl.textContent = err.message
          + '. The Executions tab in n8n shows which node stopped.';
      })
      .finally(function () { go.disabled = false; });
  });
</script>
</body>
</html>`;

return [{ json: { html } }];

// Same node name, same output shape, different source. The page posts the CV
// as an uploaded file and the job ad as a text field; Extract CV Text has
// already turned the PDF into plain text. Everything downstream reads Intake
// by name and only wants { cv, job_ad }, so nothing after this changes.

return [{
  json: {
    cv: $json.text,
    job_ad: $('Web UI').first().json.body.job_ad,
  },
}];

// Plain JavaScript. No model runs here, so this number is the same every
// run and you can point at exactly which requirement cost the points.
// Merge sits upstream only to make sure both parsers finished first.

function toJson(raw) {
  // Matches a three-backtick fence. Written as a quantifier so this line can be
  // pasted inside a fenced code block without ending it.
  const fence = /`{3}(?:json)?/g;
  const body = String(raw).replace(fence, '').trim();
  try {
    return JSON.parse(body);
  } catch (err) {
    return null;
  }
}

// Merge hands both parser outputs to this node in order: input 1 is the CV
// parser, input 2 is the job ad parser. Reading them positionally means this
// node does not care what you named those two nodes.
const items = $input.all();

if (items.length < 2) {
  throw new Error('Expected two items from Merge, one from each parser. Check '
    + 'that both parsers ran and that each is wired to a different Merge input.');
}

const cv = toJson(items[0].json.text);
const job = toJson(items[1].json.text);

if (!cv || !job) {
  throw new Error('A parser did not return clean JSON. Open that node and read '
    + 'its output - that failure is the real signal.');
}

// Everything the CV can prove, as lists of whole words.
const words = (s) => String(s).toLowerCase().match(/[a-z0-9+#.]+/g) || [];
const have = [...(cv.skills || []), ...(cv.roles || []).map(r => r.title || '')]
  .map(words)
  .filter(w => w.length);

// Whole words only, in both directions. The CV saying "kubernetes" satisfies an
// ad asking for "kubernetes in production". Substring matching would have let
// "django" satisfy a requirement for "go", which is how you ship a wrong score.
function met(requirement) {
  const want = words(requirement);
  if (!want.length) return false;
  return have.some(got => want.every(w => got.includes(w))
    || got.every(g => want.includes(g)));
}

const must = job.must_have || [];
const nice = job.nice_to_have || [];
const missing = must.filter(r => !met(r));
const bonus = nice.filter(r => met(r));
const score = must.length
  ? Math.round(((must.length - missing.length) / must.length) * 100)
  : 0;

// Years come from the earliest role the parser could read a year out of.
const startYears = (cv.roles || [])
  .map(r => String(r.start || '').match(/\d{4}/))
  .filter(Boolean)
  .map(m => Number(m[0]));
const years = startYears.length
  ? new Date().getFullYear() - Math.min(...startYears)
  : 0;
const yearsRequired = job.years_required || 0;

return [{
  json: {
    score,
    missing,
    bonus,
    years,
    years_required: yearsRequired,
    years_ok: years >= yearsRequired,
    must_have: must,
    cv,
    job,
  },
}];

parameters.text:
=Rewrite this CV for this specific job.

Reorder and reword freely. Never add a title, date, tool or achievement that is
not in the CV below. If the CV cannot back something the job asks for, leave it
out - do not invent it.

Return only the rewritten CV as plain text. No preamble, no closing note, no
commentary of any kind.

CV:
{{ $('Intake').first().json.cv }}

THIS JOB WANTS: {{ JSON.stringify($json.must_have) }}
THE CV CANNOT SHOW: {{ JSON.stringify($json.missing) }}

