// Turns the score and the rewritten CV into a report. Two versions of the same
// thing: html for the page, text for anywhere that cannot render it.
//
// The html carries classes and data attributes but no styling of its own - the
// page it is injected into owns every colour and size. Change the look there.

// Shown in the credit line. Update these if you change the model nodes.
const CV_MODEL = 'google/gemini-3.1-flash-lite';
const JOB_MODEL = 'minimax/minimax-m3';
const WRITER_MODEL = 'claude-sonnet-4-6';

const scored = $('Score').first().json;
// This node's input IS the Tailor output, so read it positionally.
const tailored = $input.first().json.text;

// None of this is ours. The job ad was typed by whoever is using the page, the
// requirements were copied out of it by a model, and the CV came back from
// another model. Escape all of it before it goes anywhere near markup.
const esc = (value) => String(value)
  .replace(/&/g, '&amp;')
  .replace(/</g, '&lt;')
  .replace(/>/g, '&gt;')
  .replace(/"/g, '&quot;')
  .replace(/'/g, '&#39;');

const tags = (items, cls, empty) => items.length
  ? `<ul class="tags ${cls}">${items.map(i => `<li>${esc(i)}</li>`).join('')}</ul>`
  : `<ul class="tags none"><li>${esc(empty)}</li></ul>`;

const total = (scored.must_have || []).length;
const met = total - scored.missing.length;
const headline = total
  ? `${met} of ${total} must-haves are in the CV`
  : 'The ad listed no named requirements';

const years = scored.years_ok
  ? `<span class="chip have">${esc(scored.years)} years, meets ` +
    `${esc(scored.years_required)}</span>`
  : `<span class="chip gap">${esc(scored.years)} years, needs ` +
    `${esc(scored.years_required)}</span>`;

const html = `
<div class="report">
  <div class="summary">
    <div class="ring" data-score="${esc(scored.score)}"
         data-label="${esc(scored.score)}%"></div>
    <div class="verdict">
      <p class="eyebrow">Match on stated requirements</p>
      <h2>${esc(headline)}</h2>
      <p class="why">Counted in a Code node, not by a model, so the same CV and
      job ad always give the same number and every lost point traces to one
      named requirement.</p>
      ${years}
    </div>
  </div>

  <div class="split">
    <section class="panel">
      <p class="eyebrow">What this CV cannot show</p>
      ${tags(scored.missing, 'gap', 'Nothing - every stated requirement is covered.')}
    </section>
    <section class="panel">
      <p class="eyebrow">Nice-to-haves it does cover</p>
      ${tags(scored.bonus, 'have', 'None of the nice-to-haves.')}
    </section>
  </div>

  <section class="panel">
    <div class="panelhead">
      <p class="eyebrow">Tailored CV</p>
      <button class="copy" type="button">Copy</button>
    </div>
    <pre class="cv">${esc(tailored)}</pre>
  </section>

  <p class="credit">CV read by <b>${esc(CV_MODEL)}</b> &middot; job ad by
  <b>${esc(JOB_MODEL)}</b> &middot; rewritten by <b>${esc(WRITER_MODEL)}</b>
  &middot; three models, one KodeKey</p>
</div>`;

const bullets = (items, empty) => items.length
  ? items.map(i => `  - ${i}`).join('\n')
  : `  - ${empty}`;

const text = [
  `ResumeRadar - ${new Date().toISOString().split('T')[0]}`,
  '',
  `${headline} (${scored.score}%)`,
  `Experience: ${scored.years} years, ` +
    `${scored.years_ok ? 'meets' : 'needs'} ${scored.years_required}`,
  '',
  'What this CV cannot show:',
  bullets(scored.missing, 'Nothing - every stated requirement is covered.'),
  '',
  'Nice-to-haves it does cover:',
  bullets(scored.bonus, 'None of the nice-to-haves.'),
  '',
  'Tailored CV:',
  '',
  tailored,
  '',
  `CV read by ${CV_MODEL}, job ad by ${JOB_MODEL}, rewritten by ` +
    `${WRITER_MODEL} - three models, one KodeKey.`,
].join('\n');

return [{
  json: {
    html,
    text,
    score: scored.score,
    missing: scored.missing,
    years_ok: scored.years_ok,
    tailored_cv: tailored,
  },
}];
